// Fonts for download-book's PDF path, as base64 so the function stays a self-contained deploy
// (a binary .ttf beside index.ts is not reliably carried by every deploy path, and the comment in
// index.ts already notes that cross-function imports aren't either). This file is a plain
// same-folder import and ships with the function like index.ts does.
//
// What they are: DejaVu Serif Regular and Bold -- the same faces the in-app exporter bundles in
// src/writing/fonts/ -- cut down to the ranges below so the function stays small (about 135 KB each
// instead of about 370 KB). Covered: Basic Latin through Cyrillic (U+0000-052F, which includes the
// combining accents U+0300-036F), Latin Extended Additional (Vietnamese, Yoruba dot-below letters),
// Greek Extended, general punctuation, currency (including the Naira sign), letterlike symbols,
// arrows and math operators. NOT covered: Arabic, Hebrew, Indic scripts, Thai, Ethiopic, CJK,
// emoji -- those still fall back to '?' (see makePdfSafe in index.ts).
//
// DejaVu fonts are free to embed and redistribute (Bitstream Vera license + public-domain changes).
//
// To regenerate (fontTools): pyftsubset DejaVuSerif.ttf --unicodes=U+0000-052F,U+1E00-1EFF,
// U+1F00-1FFF,U+2000-206F,U+20A0-20CF,U+2100-214F,U+2190-21FF,U+2200-22FF --layout-features='*'
// --no-hinting --output-file=out.ttf, then base64 the result into the matching constant below.

export const DEJAVU_SERIF_REGULAR_B64 =
  '';

export const DEJAVU_SERIF_BOLD_B64 =
  '';
